  const projected=linear(a.context,w.wo),residual1=add(x,projected),n2=layerNorm(residual1);
  const ffPre=linear(n2.value,w.w1),ffAct=ffPre.map(gelu),ffOut=linear(ffAct,w.w2),out=add(residual1,ffOut);
